'use strict';

function createAccessDialog(checkCredentials) {
  if (typeof checkCredentials !== 'function') {
    throw new TypeError('checkCredentials must be a function');
  }

  let state = { visible: false, busy: false, message: null };
  const copy = () => ({ ...state });

  function open() {
    state = { visible: true, busy: false, message: null };
    return copy();
  }

  function close() {
    state = { visible: false, busy: false, message: null };
    return copy();
  }

  async function submit(credentials) {
    if (!state.visible || state.busy) return copy();
    if (
      credentials === null ||
      typeof credentials !== 'object' ||
      typeof credentials.user !== 'string' ||
      credentials.user.length === 0 ||
      typeof credentials.secret !== 'string' ||
      credentials.secret.length === 0
    ) {
      state = { visible: true, busy: false, message: 'invalid input' };
      return copy();
    }

    state = { visible: true, busy: true, message: state.message };
    try {
      const reply = await checkCredentials({ user: credentials.user, secret: credentials.secret });
      const code = reply !== null && typeof reply === 'object' && Number.isInteger(reply.code)
        ? reply.code
        : null;
      if (code === 204) state = { visible: false, busy: false, message: 'accepted' };
      else if (code === 401) state = { visible: true, busy: false, message: 'denied' };
      else if (code === 409) state = { visible: true, busy: false, message: 'denied' };
      else state = { visible: true, busy: false, message: 'service error' };
    } catch (_) {
      state = { visible: true, busy: false, message: 'service error' };
    }
    return copy();
  }

  return { open, close, getState: copy, submit };
}

module.exports = { createAccessDialog };

