'use strict';

const assert = require('node:assert');
const api = require('./solution');
assert.deepStrictEqual(Object.keys(api), ['createAccessDialog']);
const { createAccessDialog } = api;

async function main() {
  for (const value of [undefined, null, {}, 'check']) {
    assert.throws(() => createAccessDialog(value), TypeError);
  }

  let calls = 0;
  let resolveCheck;
  let checkerCredentials;
  const dialog = createAccessDialog((credentials) => {
    calls += 1;
    checkerCredentials = credentials;
    return new Promise((resolve) => { resolveCheck = resolve; });
  });

  assert.deepStrictEqual(dialog.getState(), { visible: false, busy: false, message: null });
  const opened = dialog.open();
  assert.deepStrictEqual(opened, { visible: true, busy: false, message: null });
  opened.visible = false;
  assert.strictEqual(dialog.getState().visible, true);

  const invalidInputs = [null, [], {}, { user: '', secret: 's' }, { user: 'u', secret: '' }, { user: 3, secret: 's' }];
  for (const credentials of invalidInputs) {
    const state = await dialog.submit(credentials);
    assert.deepStrictEqual(state, { visible: true, busy: false, message: 'invalid input' });
    state.message = 'changed';
    assert.strictEqual(dialog.getState().message, 'invalid input');
  }
  assert.strictEqual(calls, 0);

  const input = { user: 'forge', secret: 'token' };
  const pending = dialog.submit(input);
  assert.strictEqual(calls, 1);
  assert.deepStrictEqual(dialog.getState(), { visible: true, busy: true, message: 'invalid input' });
  assert.notStrictEqual(checkerCredentials, input);
  assert.deepStrictEqual(checkerCredentials, input);
  input.user = 'mutated';
  assert.strictEqual(checkerCredentials.user, 'forge');

  const busyState = await dialog.submit({ user: 'other', secret: 'other' });
  assert.deepStrictEqual(busyState, dialog.getState());
  assert.strictEqual(calls, 1);
  resolveCheck({ code: 401 });
  assert.deepStrictEqual(await pending, { visible: true, busy: false, message: 'denied' });

  assert.deepStrictEqual(dialog.close(), { visible: false, busy: false, message: null });
  assert.deepStrictEqual(dialog.open(), { visible: true, busy: false, message: null });

  async function outcome(reply, expected) {
    const d = createAccessDialog(async () => reply);
    d.open();
    assert.deepStrictEqual(await d.submit({ user: 'u', secret: 's' }), expected);
  }

  await outcome({ code: 204 }, { visible: false, busy: false, message: 'accepted' });
  await outcome({ code: 409 }, { visible: true, busy: false, message: 'retry later' });
  await outcome({ code: 500 }, { visible: true, busy: false, message: 'service error' });
  await outcome({ code: 204.5 }, { visible: true, busy: false, message: 'service error' });
  await outcome(null, { visible: true, busy: false, message: 'service error' });

  const rejecting = createAccessDialog(async () => { throw new Error('offline'); });
  rejecting.open();
  assert.deepStrictEqual(await rejecting.submit({ user: 'u', secret: 's' }), {
    visible: true, busy: false, message: 'service error'
  });
}

main().catch((error) => {
  console.error(error);
  process.exitCode = 1;
});

